/* Writes games/red-mesa-rally/CODEMAP.md: every script file in load order with what it declares
   (constants, functions, classes and their methods) and the line each starts at.
     npm run rmr:map        (also part of npm run check:rmr)
   It is generated from the code, so it cannot go stale: rerun it after changes and commit the result. */
import { readFileSync, writeFileSync } from 'node:fs';
import { join } from 'node:path';
import * as espree from 'espree';
import { GAME_DIR, scriptList } from './lib.mjs';

const out = ['# Red Mesa Rally code map', '',
  'Generated by `npm run rmr:map` (test/rmr/codemap.mjs). Do not edit by hand.',
  'Files in load order. `name:line`; methods are listed under their class, also when another file adds them', 'with `Object.assign(Class.prototype, { ... })`.', ''];
let total = 0;
for (const f of scriptList()) {
  const src = readFileSync(join(GAME_DIR, f), 'utf8'), lines = src.split('\n').length - 1;
  total += lines;
  const title = (src.match(/^\/\* Red Mesa Rally · (.*?) \*\/$/m) || [])[1] || '';
  out.push(`## ${f} (${lines} lines, ${Math.round(src.length / 1024)} KB)`, title, '');
  const plain = [], line = (n) => n.loc.start.line;
  const methods = (owner, props) => out.push(`- **${owner}** ` + props.filter((p) => p.key && (p.key.name || p.key.value) && p.kind !== 'constructor')
    .map((p) => `${p.static ? 'static ' : ''}${p.key.name || p.key.value}:${line(p)}`).join(' · '));
  const flush = () => { if (plain.length) out.push('- ' + plain.splice(0).join(' · ')); };
  for (const node of espree.parse(src, { ecmaVersion: 'latest', loc: true }).body) {
    if (node.type === 'VariableDeclaration') for (const d of node.declarations) plain.push(`${d.id.name || src.slice(d.id.range?.[0], d.id.range?.[1]) || '{…}'}:${line(d)}`);
    else if (node.type === 'FunctionDeclaration') plain.push(`${node.id.name}():${line(node)}`);
    else if (node.type === 'ClassDeclaration') { flush(); methods(`class ${node.id.name}:${line(node)}`, node.body.body); }
    else if (node.type === 'ExpressionStatement' && node.expression.type === 'CallExpression') {
      const c = node.expression, t = c.arguments[0], o = c.arguments[1];
      // Object.assign(Game.prototype, { ... })
      if (c.callee.object?.name === 'Object' && c.callee.property?.name === 'assign' && t?.property?.name === 'prototype' && o?.type === 'ObjectExpression') { flush(); methods(`${t.object.name} (added):${line(node)}`, o.properties); }
    }
  }
  flush(); out.push('');
}
out.push(`Total: ${scriptList().length} files, ${total} lines.`, '');
writeFileSync(join(GAME_DIR, 'CODEMAP.md'), out.join('\n'));
console.log(`wrote games/red-mesa-rally/CODEMAP.md (${scriptList().length} files, ${total} lines)`);
